-- PROJECT ECHO, Build 42.21, visual-only test patch v0.2.
-- Both effects are client side. No vanilla scripts, ground world models, recipes,
-- game statistics, or sleeping bag pack/unpack behavior are modified.
-- The sleeping-bag held-model aliases are generated by INSTALL.bat from local game scripts.

local HANDLE_ITEM = "Base.SmallHandle"
local HANDLE_MODEL_CANDIDATES = {
    "Base.WoodenStick_Hand",
    "Base.ShortBat",
}
local BAG_PREFIX = "Base.SleepingBag_"
local BAG_ORIGINAL_PREFIX = "SleepingBag_Rolled_"
local BAG_ALIAS_PREFIX = "PE_Echo_SleepingBag_Rolled_"

local previouslySet = setmetatable({}, { __mode = "k" })
local bagUnknown = {}
local modelLookup = {}
local handleModel = nil
local handleLookupDone = false
local handleErrors = {}

local function existsModel(fullName)
    local cached = modelLookup[fullName]
    if cached ~= nil then return cached end
    if not ScriptManager or not ScriptManager.instance then return false end
    local ok, script = pcall(function()
        return ScriptManager.instance:getModelScript(fullName)
    end)
    local exists = ok and script ~= nil
    modelLookup[fullName] = exists
    return exists
end

local function handleReplacement()
    if handleLookupDone then return handleModel end
    handleLookupDone = true
    for _, candidate in ipairs(HANDLE_MODEL_CANDIDATES) do
        if existsModel(candidate) then
            handleModel = candidate
            print("[PE-3DFix] Handle fallback model: " .. candidate)
            break
        end
    end
    if not handleModel then
        print("[PE-3DFix] Missing vanilla handle fallback; handle untouched")
    end
    return handleModel
end

local function isSleepingBag(fullType)
    return fullType and fullType:sub(1, #BAG_PREFIX) == BAG_PREFIX
end

local function bagReplacement(item)
    local current = item:getStaticModel()
    if not current or current == "" then return nil end
    local baseName = current:match("([^%.]+)$") or current
    -- We fix only vanilla rolled models, never unfolded tent/placement geometry.
    if baseName:sub(1, #BAG_ALIAS_PREFIX) == BAG_ALIAS_PREFIX then return nil end
    if baseName:sub(1, #BAG_ORIGINAL_PREFIX) ~= BAG_ORIGINAL_PREFIX then
        if not bagUnknown[current] then
            bagUnknown[current] = true
            print("[PE-3DFix] Bag model not targeted: " .. tostring(item:getFullType())
                .. " = " .. tostring(current))
        end
        return nil
    end
    local alias = "Base.PE_Echo_" .. baseName
    if existsModel(alias) then return alias end
    if not bagUnknown[alias] then
        bagUnknown[alias] = true
        print("[PE-3DFix] Bag model alias missing: " .. alias
            .. " (run INSTALL.bat to generate aliases from the local game)")
    end
    return nil
end

local function applyModel(player, item, model, label)
    if not model then return end
    if previouslySet[item] then return end
    local old = item:getStaticModel()
    if old == model then return end
    local ok, err = pcall(function()
        item:setStaticModel(model)
        if player.resetModelNextFrame then player:resetModelNextFrame() end
    end)
    if ok then
        previouslySet[item] = old
        print("[PE-3DFix] " .. label .. " held: " .. tostring(old) .. " -> " .. model)
    elseif not handleErrors[tostring(err)] then
        handleErrors[tostring(err)] = true
        print("[PE-3DFix] Failed to apply held-model workaround: " .. tostring(err))
    end
end

local function restoreModel(player, item)
    local original = previouslySet[item]
    if not original then return end
    local ok, err = pcall(function()
        item:setStaticModel(original)
        if player.resetModelNextFrame then player:resetModelNextFrame() end
    end)
    if ok then
        previouslySet[item] = nil
    elseif not handleErrors[tostring(err)] then
        handleErrors[tostring(err)] = true
        print("[PE-3DFix] Failed restoring original model: " .. tostring(err))
    end
end

local playerHands = setmetatable({}, { __mode = "k" })
local function onPlayerUpdate(player)
    if not player or player:isDead() or not player:isLocalPlayer() then return end
    local hands = playerHands[player]
    if not hands then
        hands = {}
        playerHands[player] = hands
    end
    local primary = player:getPrimaryHandItem()
    local secondary = player:getSecondaryHandItem()

    -- Restore when the item leaves either hand. This preserves regular world display.
    if hands.primary and hands.primary ~= primary and hands.primary ~= secondary then
        restoreModel(player, hands.primary)
    end
    if hands.secondary and hands.secondary ~= primary and hands.secondary ~= secondary then
        restoreModel(player, hands.secondary)
    end
    hands.primary, hands.secondary = primary, secondary

    local function update(item)
        if not item then return end
        local typ = item:getFullType()
        if typ == HANDLE_ITEM then
            if item:isBroken() then
                applyModel(player, item, handleReplacement(), "Broken handle")
            else
                restoreModel(player, item)
            end
        elseif isSleepingBag(typ) then
            applyModel(player, item, bagReplacement(item), "Sleeping bag")
        end
    end
    update(primary)
    if secondary ~= primary then update(secondary) end
end

if Events and Events.OnPlayerUpdate then
    Events.OnPlayerUpdate.Add(onPlayerUpdate)
end
print("[PE-3DFix] v0.2 loaded (broken small handle + sleeping bags)")
